<?php $pageTitle='ONGs';require __DIR__.'/includes/header.php';global $ongs;?><section class="page-hero"><div class="container"><span class="eyebrow">Rede Guardião</span><h1>Gente diferente. Uma mesma vontade de ajudar.</h1><p>As organizações abaixo são fictícias e servem para demonstrar como o sistema pode apresentar parceiros, seus focos de atuação e os animais ligados a cada história.</p></div></section><section class="section"><div class="container"><div class="filters"><button class="filter active" data-filter="todos">Todas</button><?php foreach(array_values(array_unique(array_map(fn($x)=>$x['foco'],$ongs))) as $f):?><button class="filter" data-filter="<?=e($f)?>"><?=e($f)?></button><?php endforeach;?></div><div class="ong-grid"><?php foreach($ongs as $id=>$o):?><article class="ong-card" data-item="<?=e($o['foco'])?>"><a href="ong.php?id=<?=$id?>"><div class="ong-photo" style="background-image:url('<?=e($o['foto'])?>')"></div><div class="ong-body"><div class="card-bottom" style="margin-top:0"><span class="chip">Fundada em <?=$o['ano']?></span><span class="meta"><?=$o['animais']?> animais</span></div><h3><?=e($o['nome'])?></h3><div class="ong-location">⌖ <?=e($o['cidade'])?> · <?=e($o['bairro'])?></div><span class="ong-focus"><?=e($o['foco'])?></span><p><?=e($o['descricao'])?></p><span class="text-link">Abrir perfil da ONG →</span></div></a></article><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php';?>
